"""Original environmental emergencies: drowning and electrical/lightning injury."""
from create_critical_heat_cold import rows,q,HE,FR,RC,ref
AH=ref('AHA special circumstances guidelines: drowning and electrocution, 2025','https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines/adult-and-pediatric-special-circumstances-of-resuscitation/')
LI=ref('Wilderness Medical Society lightning injury guideline','https://doi.org/10.1016/j.wem.2014.08.011')
BU=ref('American Burn Association referral guidance','https://www.ameriburn.org/burn-care-team/resources/guidelines-for-burn-patient-referral')

q('What is the accepted definition of drowning?', 'A process of respiratory impairment from submersion or immersion in liquid',[
 ('Any death occurring near water regardless of respiratory impairment','The definition concerns a specific respiratory process.'),('Only fatal aspiration of freshwater','Drowning can be nonfatal and occurs in different liquids.'),('Any brief water contact without breathing impairment','Water contact alone does not meet the definition.')],
 'Use a process definition rather than obsolete labels','**Drowning can result in death, morbidity or no morbidity.**',['Terms such as near-drowning and dry drowning can confuse communication.','Respiratory impairment is the central event.'],'**Describe the exposure and actual clinical consequences.**',['Record submersion duration, resuscitation and current respiratory/neurological findings.','Assess trauma, hypothermia and medical causes of the event.'],[['Core process','Respiratory impairment'],['Outcome','Fatal or nonfatal'],['Documentation','Specific findings and course']],[AH])

q('A trained rescuer removes an unresponsive, pulseless drowning victim from water. Which resuscitation principle is especially important?', 'Provide CPR with breaths as well as compressions, using the first available effective ventilation method',[
 ('Compression-only CPR is the preferred complete treatment for the hypoxic mechanism','Ventilation is especially important after drowning.'),('Delay breaths until advanced intubation equipment arrives','Available effective breathing support should not be delayed.'),('Perform prolonged abdominal thrusts to drain water before CPR','This delays resuscitation and risks regurgitation.')],
 'Reverse the hypoxic mechanism promptly','**Drowning arrest usually follows respiratory failure.**',['Trained rescuers may begin with breaths without delaying compressions.','Provide breaths by a method appropriate to training and available equipment.'],'**Start effective resuscitation and use the AED when available.**',['Do not attempt to expel lung water before ventilation.','Keep rescuer safety central during extraction.'],[['Mechanism','Hypoxemia'],['CPR','Compressions plus breaths'],['Equipment','Use available effective means']],[AH],style='clinical_scenario')

q('A breathing patient is rescued after submersion and develops hypoxemia with bilateral pulmonary opacities. What is the principal early lung mechanism?', 'Aspiration-related surfactant dysfunction and alveolar-capillary injury causing shunt',[
 ('A required massive intravascular absorption causing a predictable serum-electrolyte pattern','Clinically important freshwater versus saltwater electrolyte distinctions are not the main initial treatment framework.'),('Pure upper-airway obstruction with no possible lower-lung injury','Aspiration can directly injure the alveolar compartment.'),('Cardiogenic edema as the only possible explanation','Noncardiogenic injury is common in this context, although cardiac causes can coexist.')],
 'Treat the respiratory physiology','**Aspirated liquid can impair gas exchange through collapse and permeability injury.**',['The amount and consequences vary.','Evaluate alternative or additional cardiac and infectious processes when appropriate.'],'**Provide oxygen and escalate respiratory support according to severity.**',['Use lung-protective ventilation if intubation is required.','Assess temperature, neurological state and the cause of submersion.'],[['Alveoli','Surfactant dysfunction/collapse'],['Barrier','Permeability injury'],['Gas exchange','Shunt and hypoxemia']],[AH],style='clinical_scenario')

q('Should routine cervical immobilization delay ventilation in every drowning rescue?', 'No; use spinal precautions when the mechanism or findings suggest injury while maintaining airway and ventilation',[
 ('Yes; all drowning events establish cervical fracture','Risk depends on diving, trauma and other evidence.'),('No; cervical injury is impossible in water','Diving and traumatic events can injure the spine.'),('Yes; a rigid collar must be fully secured before any breathing support','Life-saving ventilation must not be deferred for routine immobilization.')],
 'Balance plausible trauma with immediate hypoxia','**The mechanism determines spinal injury suspicion.**',['Manual stabilization can be used while the airway is managed.','Avoid unnecessary rescue delays in a nontraumatic event.'],'**Resuscitate and assess trauma in parallel.**',['Document diving, impact, neck pain and focal deficits.','Use appropriate motion restriction when indicated.'],[['Nontraumatic event','No automatic spinal diagnosis'],['Diving/impact','Higher suspicion'],['Priority','Oxygenation and ventilation']],[AH])

q('After drowning, a patient is initially stable but has persistent cough, tachypnea and oxygen saturation 91% on air. Which disposition is appropriate?', 'Clinical observation and respiratory evaluation rather than immediate discharge',[
 ('Discharge because the initial rescue was successful','Persistent symptoms and hypoxemia indicate ongoing injury.'),('Ignore symptoms if the first chest radiograph is normal','Clinical abnormalities can precede radiographic changes.'),('Diagnose inevitable fatal delayed drowning without assessment','Use the actual evolving respiratory illness rather than an alarmist label.')],
 'Disposition follows physiology, not the fact of rescue','**Persistent respiratory findings require monitored assessment.**',['Gas exchange can worsen after aspiration-related injury.','Observation and treatment intensity depend on symptoms and response.'],'**Escalate oxygen and support as needed.**',['Assess associated trauma, hypothermia and the precipitating illness.','Discharge criteria require an appropriately reassuring clinical course.'],[['Symptoms','Persistent cough/tachypnea'],['SpO2','Hypoxemic'],['Plan','Observe and treat']],[AH],style='clinical_scenario')

q('Which associated factor should be actively investigated in an adult who loses consciousness while swimming before submersion?', 'A precipitating cardiac, neurological or metabolic event',[
 ('Assume water aspiration must have preceded the loss of consciousness','The sequence can be the reverse.'),('Attribute every event to inadequate swimming skill','This misses treatable causes such as arrhythmia, seizure or hypoglycemia.'),('Exclude cardiac disease because the lungs are now abnormal','Secondary aspiration injury can coexist with the original cardiac event.')],
 'The drowning event may be a consequence of another emergency','**History of symptoms before submersion can change the diagnostic pathway.**',['Obtain witness accounts and relevant family/drug history.','ECG, glucose and targeted neurological assessment are often important.'],'**Treat both the respiratory injury and the precipitating cause.**',['Consider inherited arrhythmia risk when appropriate.','Plan prevention and return-to-activity advice after diagnosis.'],[['Before submersion','Syncope/seizure/metabolic cause'],['After submersion','Respiratory injury'],['Evaluation','Both causal levels']],[AH],style='clinical_scenario')

q('Before touching a person still in contact with an electrical source, what is the rescuer priority?', 'Ensure the electrical supply is isolated and the scene is safe',[
 ('Pull the patient away with bare hands immediately','This can electrocute the rescuer.'),('Pour water over the live source to cool it','This can create additional conductive hazards.'),('Assume low-voltage domestic current is harmless','Domestic current can cause fatal dysrhythmia and injury.')],
 'A second casualty cannot provide effective rescue','**Electrical contact must be interrupted safely.**',['Use trained services and appropriate equipment for high-voltage hazards.','Do not approach fallen power lines as though the surrounding ground is safe.'],'**After safe access, assess breathing and circulation immediately.**',['Provide CPR/AED treatment when indicated.','Evaluate burns, trauma and hidden deep injury.'],[['Scene','Electrical isolation'],['Rescue','Safe access'],['Patient','ABC and associated injuries']],[AH])

q('A high-voltage electrical injury leaves small skin wounds but severe limb pain, swelling and elevated CK. Which conclusion is correct?', 'Deep tissue injury can be much greater than the visible skin burn suggests',[
 ('Small surface wounds prove only a minor exposure','Current can damage muscle and deeper structures along its path.'),('CK elevation excludes electrical injury','Muscle injury can cause rhabdomyolysis.'),('Normal skin color excludes compartment syndrome','Deep swelling can threaten compartments despite limited skin changes.')],
 'Surface appearance underestimates some electrical injuries','**Current-related heating and tissue injury can occur below the skin.**',['Assess muscle injury, perfusion, compartments and neurological function.','Falls or violent contraction can cause additional trauma.'],'**Arrange burn/trauma specialist care and monitor renal/electrolyte complications.**',['Follow ECG and hemodynamic findings according to exposure risk.','Treat hyperkalemia promptly when present.'],[['Skin','May show limited wounds'],['Deep tissue','Muscle/vascular injury'],['Systemic','Rhabdomyolysis and arrhythmia risk']],[BU],style='clinical_scenario')

q('Which rhythm is a major immediate hazard of electrical current traversing the chest?', 'Ventricular fibrillation',[
 ('Only benign sinus arrhythmia','Potentially fatal ventricular dysrhythmias can occur.'),('Atrial flutter as the exclusive electrical-injury rhythm','The rhythm spectrum includes more dangerous ventricular disturbances.'),('A fixed paced rhythm generated by all electrical contacts','External current does not create a safe permanent pacemaker.')],
 'The pathway and current characteristics affect risk','**Electrical exposure can abruptly disrupt cardiac activation.**',['Respiratory arrest and trauma can also contribute to collapse.','A normal appearance does not establish a perfusing rhythm.'],'**Assess circulation promptly and use standard CPR/defibrillation when indicated.**',['Obtain an ECG and determine monitoring needs from the clinical exposure.','Loss of consciousness, symptoms or abnormal ECG warrant particular attention.'],[['Immediate threat','VF or other arrest'],['Treatment','CPR/AED/ALS'],['Further assessment','ECG, symptoms and injury pathway']],[AH])

q('In a lightning mass-casualty event, what does reverse triage mean?', 'Prioritize apparently lifeless victims for immediate resuscitation because respiratory/cardiac arrest may be reversible',[
 ('Automatically label every apneic victim as unsalvageable','Lightning-related arrest can respond to prompt support.'),('Treat walking wounded before all nonbreathing victims','This can miss a short window for successful resuscitation.'),('Delay resuscitation until burn depth is calculated','Burn appearance is not the immediate triage priority.')],
 'Lightning can produce a uniquely reversible arrest pattern','**Respiratory-center paralysis can persist after cardiac activity returns.**',['Ventilatory support can prevent a secondary hypoxic arrest.','Scene safety and the risk of further strikes remain important.'],'**Provide early CPR and breathing support to appropriate victims.**',['Do not confuse lightning triage with all other mass-casualty algorithms.','Assess survivors for trauma, neurological and cardiac injury.'],[['Triage emphasis','Apparently lifeless victims'],['Mechanism','Reversible arrest/apnea'],['Support','Early resuscitation and ventilation']],[LI])

q('After lightning injury, a patient has transient weak, pale, cold legs with reduced pulses that improve over hours. Which syndrome is suggested?', 'Keraunoparalysis',[
 ('A proven permanent spinal transection based on the initial examination alone','A transient autonomic/vascular syndrome can mimic cord injury.'),('Acute inflammatory demyelinating polyneuropathy as the characteristic immediate mechanism','That usually has a different time course.'),('A harmless finding that excludes associated trauma','Spinal and vascular injuries still need assessment.')],
 'A transient lightning syndrome can mimic structural injury','**Autonomic vasoconstriction and neurological dysfunction can produce keraunoparalysis.**',['Recovery can be rapid, but the diagnosis must not conceal trauma.','Persistent deficits require investigation.'],'**Maintain appropriate precautions and reassess serially.**',['Evaluate perfusion and neurological function.','Investigate spinal or vascular injury when findings or mechanism warrant it.'],[['Findings','Transient paresis/pallor/cold limbs'],['Course','Often improves'],['Safety','Exclude structural injury']],[LI],style='clinical_scenario')

q('Which delayed problem should be considered after a lightning strike even when initial resuscitation succeeds?', 'Neurological, auditory and ocular sequelae including cataract',[
 ('No follow-up is needed if there is no large skin burn','Significant noncutaneous injury can occur.'),('Only tetanus is relevant after discharge','Neurological and sensory complications can be important.'),('All later symptoms prove recurrent electrical current in the body','The body does not retain a dangerous charge after the strike.')],
 'Electrical survival does not exclude later disability','**Lightning can injure nervous, visual and auditory systems.**',['Tympanic membrane injury and neurocognitive symptoms may need follow-up.','Some consequences are not obvious at the initial examination.'],'**Provide targeted assessment and clear return advice.**',['Arrange referral for persistent sensory or neurological findings.','Record the exposure and immediate clinical course.'],[['Immediate','Arrest/trauma'],['Later','Neurological and sensory effects'],['Follow-up','Symptom-directed evaluation']],[LI,BU])
